starter_code:
#include <iostream>
#include <iomanip>
using namespace std;

int main() {
    int a, b, c;
    cout << "Enter three scores: ";
    cin >> a >> b >> c;

    int total = a + b + c;
    double average = total / 3;

    cout << fixed << setprecision(2);
    cout << "Average: " << average << endl;
    return 0;
}

